<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class AuditController extends Controller{
 public function index(Request$r){$c=$r->user()->company_id;$q=DB::table('audit_events as a')->leftJoin('users as u','u.id','=','a.user_id')->where('a.company_id',$c)->select('a.*','u.name as user_name','u.email as user_email');if($r->filled('user_id'))$q->where('a.user_id',$r->user_id);if($r->filled('entity'))$q->where('a.entity',$r->entity);if($r->filled('event'))$q->where('a.event',$r->event);if($r->filled('from'))$q->whereDate('a.created_at','>=',$r->from);if($r->filled('to'))$q->whereDate('a.created_at','<=',$r->to);if($r->boolean('critical'))$q->where(fn($x)=>$x->where('a.event','like','%cancel%')->orWhere('a.event','like','%password%')->orWhere('a.event','like','%permission%')->orWhere('a.event','like','%delete%')->orWhere('a.event','like','%restore%'));return response()->json(['success'=>true,'data'=>$q->latest('a.created_at')->limit(1000)->get()]);}
 public function summary(Request$r){$c=$r->user()->company_id;return response()->json(['success'=>true,'data'=>['total'=>DB::table('audit_events')->where('company_id',$c)->count(),'today'=>DB::table('audit_events')->where('company_id',$c)->whereDate('created_at',today())->count(),'users'=>DB::table('audit_events')->where('company_id',$c)->distinct('user_id')->count('user_id'),'entities'=>DB::table('audit_events')->where('company_id',$c)->select('entity',DB::raw('COUNT(*) total'))->groupBy('entity')->orderByDesc('total')->get(),'events'=>DB::table('audit_events')->where('company_id',$c)->distinct()->orderBy('event')->pluck('event'),'user_options'=>DB::table('users')->where('company_id',$c)->select('id','name')->get()]]);}
 public function show(Request$r,int$id){return response()->json(['success'=>true,'data'=>DB::table('audit_events as a')->leftJoin('users as u','u.id','=','a.user_id')->where(['a.id'=>$id,'a.company_id'=>$r->user()->company_id])->select('a.*','u.name as user_name','u.email as user_email')->firstOrFail()]);}
}
